package br.com.fiap.bank.plataforma.legacy;
import br.com.fiap.bank.plataforma.application.CreditoApplicationService; import br.com.fiap.bank.plataforma.application.dto.*; import org.springframework.web.bind.annotation.*; import org.springframework.http.*; import jakarta.validation.Valid; import java.util.*; @CrossOrigin(origins = "http://localhost:4200") @RestController @RequestMapping("/api/credito") public class CreditoLegacyAdapterController {private final CreditoApplicationService service;public CreditoLegacyAdapterController(CreditoApplicationService s){service=s;} @PostMapping("/solicitarCredito") public ResponseEntity<SolicitacaoCreditoResponseDTO> solicitar(@Valid @RequestBody SolicitarCreditoRequest r){return ResponseEntity.ok(service.solicitar(r));} @PostMapping("/consultarStatusCredito") public List<SolicitacaoCreditoResponseDTO> status(@RequestBody Map<String,String> r){return service.listarPorCpf(r.getOrDefault("cpfCliente",""));} @PostMapping("/buscarSolicitacaoPorId") public SolicitacaoCreditoResponseDTO buscar(@RequestBody Map<String,Long> r){return service.buscar(r.get("solicitacaoId"));} @PostMapping("/listarTodasSolicitacoes") public List<SolicitacaoCreditoResponseDTO> listar(){return service.listar();} @PostMapping("/aprovarSolicitacao") public SolicitacaoCreditoResponseDTO aprovar(@RequestBody Map<String,Object> r){return service.decidir(Long.valueOf(r.get("solicitacaoId").toString()),"APROVADO",Objects.toString(r.get("parecerOperador"),"Aprovado pela Mesa de Operações."));} @PostMapping("/reprovarSolicitacao") public SolicitacaoCreditoResponseDTO reprovar(@RequestBody Map<String,Object> r){return service.decidir(Long.valueOf(r.get("solicitacaoId").toString()),"REPROVADO",Objects.toString(r.get("motivoReprovacao"),"Reprovado pela Mesa de Operações."));} @PostMapping("/consultarClienteCore") public Map<String,Object> conta(@RequestBody Map<String,String> r){return service.consultarConta(r.getOrDefault("cpfCliente",""));} }
